effect.shader:
vec3 linear(vec3 c) {
    return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(vec3(0.04045), c));
}
vec3 srgb(vec3 l) {
    l = clamp(l, 0.0, 1.0);
    return mix(l * 12.92, 1.055 * pow(l, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), l));
}
// O filtro linear do RT do Node: os 4 texels em luz linear, pré-multiplicados (Clamp nas bordas).
vec4 lerComoONode(highp sampler2D t, vec2 uv) {
    ivec2 T = textureSize(t, 0);
    vec2 p = uv * vec2(T) - 0.5;
    ivec2 i = ivec2(floor(p));
    vec2 f = p - floor(p);
    vec4 s = vec4(0.0);
    for (int k = 0; k < 4; k++) {
        ivec2 o = ivec2(k & 1, k >> 1);
        vec4 c = texelFetch(t, clamp(i + o, ivec2(0), T - 1), 0);
        float w = (o.x == 1 ? f.x : 1.0 - f.x) * (o.y == 1 ? f.y : 1.0 - f.y);
        s += w * vec4(linear(c.rgb) * c.a, c.a);
    }
    return s;
}
// Ponto do Nova → UV do Node (Y para cima).
vec2 doNode(vec2 p) { return acEntradaDePe == 1 ? p : vec2(p.x, 1.0 - p.y); }
void main()
{
    vec2 p0 = doNode(point0), p1 = doNode(point1), p2 = doNode(point2), p3 = doNode(point3);
    // CalcHomographyMatrix, conta por conta.
    float sx = p0.x - p1.x - p2.x + p3.x;
    float sy = p0.y - p1.y - p2.y + p3.y;
    float a = (p1.x - p3.x) * (p2.y - p3.y);
    float b = (p2.x - p3.x) * (p1.y - p3.y);
    float g = (sx * (p1.y - p3.y) - (p1.x - p3.x) * sy) / (b - a);
    float h = (sx * (p2.y - p3.y) - (p2.x - p3.x) * sy) / (a - b);
    mat3 H = mat3(p2.x - p0.x + p2.x * g, p2.y - p0.y + p2.y * g, g,
                  p1.x - p0.x + p1.x * h, p1.y - p0.y + p1.y * h, h,
                  p0.x, p0.y, 1.0);
    if (abs(determinant(H)) < 1e-12) { fragColor = vec4(0.0); return; }
    // O UV da tela no Node (Y para cima) e o lugar da camada nele.
    vec2 q = acEntradaDePe == 1 ? acScreenNorm : vec2(acScreenNorm.x, 1.0 - acScreenNorm.y);
    vec3 s = inverse(H) * vec3(q, 1.0);
    vec2 uv = s.xy / s.z;
    if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) { fragColor = vec4(0.0); return; }
    if (acEntradaDePe != 1) uv.y = 1.0 - uv.y;
    vec4 c = lerComoONode(inputImg, uv);
    fragColor = c.a > 1e-5 ? vec4(srgb(c.rgb / c.a), c.a) : vec4(0.0);
}
